// Validation des paramètres
const input = $input.first().json;
const body = input.body || input;

const document = body.document || {};
const jobType = body.job_type || 'pdf_translation';
const sourceLanguage = body.source_language || 'he';
const targetLanguage = body.target_language || 'fr';
const mode = body.mode || 'premium';
const apiKey = body.api_key || '';
const openaiApiKey = body.openai_api_key || '';
const projectId = body.project_id || '';
const requestId = body.request_id || null;

// Validation
const errors = [];
if (!document.content) errors.push('document.content requis');
if (!document.type) errors.push('document.type requis (pdf, text, url)');
if (!apiKey) errors.push('api_key (Anthropic) requis');
if (!openaiApiKey) errors.push('openai_api_key requis');
if (!projectId) errors.push('project_id requis');

// Générer un job_id unique
const jobId = 'doc_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);

// Déterminer le nombre de pages
const totalPages = document.total_pages || 1;

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    jobId: jobId,
    jobType: jobType,
    document: document,
    totalPages: totalPages,
    sourceLanguage: sourceLanguage,
    targetLanguage: targetLanguage,
    mode: mode,
    apiKey: apiKey,
    openaiApiKey: openaiApiKey,
    projectId: projectId,
    requestId: requestId,
    startTime: Date.now()
  }
}];

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

// Extraire job_id de la réponse API ou utiliser celui généré
const apiJobId = input.body?.id || input.body?.job_id || input.id || input.job_id;
const jobId = apiJobId || prevData.jobId;

return [{
  json: {
    ...prevData,
    jobId: jobId,
    apiResponse: input.body || input
  }
}];

// Récupérer les données
const prevData = $('Prepare Response').first().json;
const document = prevData.document;
const totalPages = prevData.totalPages;

// Créer un item par page
const pages = [];
for (let i = 0; i < totalPages; i++) {
  pages.push({
    json: {
      pageIndex: i,
      pageNumber: i + 1,
      totalPages: totalPages,
      jobId: prevData.jobId,
      jobType: prevData.jobType,
      document: document,
      sourceLanguage: prevData.sourceLanguage,
      targetLanguage: prevData.targetLanguage,
      mode: prevData.mode,
      apiKey: prevData.apiKey,
      openaiApiKey: prevData.openaiApiKey,
      projectId: prevData.projectId,
      requestId: prevData.requestId,
      startTime: prevData.startTime
    }
  });
}

return pages;

// Extraire le contenu de la page actuelle
const input = $input.first().json;
const document = input.document;
const pageIndex = input.pageIndex;

// Selon le type de document, extraire le contenu
let pageContent = '';

if (document.type === 'text') {
  // Si c'est du texte, on divise par pages (approximatif)
  const lines = (document.content || '').split('\n');
  const linesPerPage = Math.ceil(lines.length / input.totalPages);
  const startLine = pageIndex * linesPerPage;
  const endLine = Math.min(startLine + linesPerPage, lines.length);
  pageContent = lines.slice(startLine, endLine).join('\n');
} else if (document.type === 'pages') {
  // Si pages pré-découpées
  pageContent = document.pages?.[pageIndex] || '';
} else {
  // PDF ou autre - le contenu devrait être pré-extrait
  pageContent = document.pages?.[pageIndex] || document.content || '';
}

return [{
  json: {
    ...input,
    pageContent: pageContent
  }
}];

const input = $input.first().json;
const prevData = $('Extract Page Content').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let translation = '';
let claudeUsage = { input_tokens: 0, output_tokens: 0, total_tokens: 0 };
let error = null;

if (statusCode >= 400 || data.error) {
  error = data.error?.message || `HTTP ${statusCode}`;
  translation = prevData.pageContent; // Fallback: texte original
} else if (data.content?.[0]?.text) {
  translation = data.content[0].text.trim();
  claudeUsage = {
    input_tokens: data.usage?.input_tokens || 0,
    output_tokens: data.usage?.output_tokens || 0,
    total_tokens: (data.usage?.input_tokens || 0) + (data.usage?.output_tokens || 0)
  };
}

return [{
  json: {
    ...prevData,
    translation: translation,
    claudeUsage: claudeUsage,
    translationError: error
  }
}];

// Accumuler les traductions dans staticData
const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;
const jobId = input.jobId;

if (!staticData.translations) {
  staticData.translations = {};
}
if (!staticData.translations[jobId]) {
  staticData.translations[jobId] = {
    pages: [],
    totalTokens: { input_tokens: 0, output_tokens: 0, total_tokens: 0 }
  };
}

// Ajouter la traduction de cette page
staticData.translations[jobId].pages[input.pageIndex] = {
  pageNumber: input.pageNumber,
  original: input.pageContent,
  translation: input.translation,
  error: input.translationError
};

// Accumuler les tokens
const usage = input.claudeUsage || { input_tokens: 0, output_tokens: 0, total_tokens: 0 };
staticData.translations[jobId].totalTokens.input_tokens += usage.input_tokens;
staticData.translations[jobId].totalTokens.output_tokens += usage.output_tokens;
staticData.translations[jobId].totalTokens.total_tokens += usage.total_tokens;

// Vérifier si c'est la dernière page
const isComplete = input.pageNumber >= input.totalPages;

return [{
  json: {
    ...input,
    isComplete: isComplete,
    accumulatedData: staticData.translations[jobId]
  }
}];

// Récupérer les traductions accumulées
const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;

// Trouver le jobId depuis les données précédentes
let jobId = null;
let result = null;

if (staticData.translations) {
  for (const [id, data] of Object.entries(staticData.translations)) {
    if (data.pages && data.pages.length > 0) {
      jobId = id;
      result = data;
      delete staticData.translations[id];
      break;
    }
  }
}

if (!result) {
  return [{ json: { success: false, reason: 'no_translations_found' } }];
}

// Combiner toutes les traductions
const fullTranslation = result.pages
  .filter(p => p)
  .map(p => p.translation)
  .join('\n\n--- Page Break ---\n\n');

return [{
  json: {
    jobId: jobId,
    success: true,
    totalPages: result.pages.filter(p => p).length,
    fullTranslation: fullTranslation,
    pages: result.pages,
    tokens: result.totalTokens,
    completedAt: Date.now()
  }
}];
